{
  "packet_id": "H6-T01-2",
  "claim_id": "C056",
  "status": "SUPPORTED",
  "claim": {
    "component_id": "C056.component",
    "value": "One case need not explain all 19 late starts.",
    "scope": "Limit on generalizing from the selected case to the full set of late starts.",
    "provenance": {
      "refs": [
        {
          "source_id": "P029",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The span explicitly supplies the case-generalization limit and the count of late starts."
    }
  },
  "signal_basis": {
    "component_id": "C056.signal_basis",
    "value": "Repeated reduction tests under fixed conditions preserve lateness in a smaller configuration of the selected case, while specified further removals cease to reproduce lateness; inconsistent outcomes remain unresolved.",
    "scope": "Replay of one selected late case, using the same predeclared repetition rule for baseline and reduced configurations.",
    "provenance": {
      "refs": [
        {
          "source_id": "P006",
          "role": "CONTEXT"
        },
        {
          "source_id": "P004",
          "role": "CONTEXT"
        },
        {
          "source_id": "P009",
          "role": "SUPPORT"
        },
        {
          "source_id": "P015",
          "role": "SUPPORT"
        },
        {
          "source_id": "P018",
          "role": "SUPPORT"
        }
      ],
      "support_status": "SUFFICIENT",
      "rationale": "The bundle identifies the selected case and defined failure, and supplies fixed test conditions, repetition and uncertainty rules, and the observed reduction pattern."
    }
  },
  "stated_empirical_relation": {
    "component_id": "C056.stated_empirical_relation",
    "value": "NOT_APPLICABLE",
    "scope": "NOT_APPLICABLE",
    "provenance": {
      "refs": [],
      "support_status": "SUFFICIENT",
      "rationale": "This supported limitation requires no unresolved empirical relation."
    }
  },
  "rationale": "Reproducing lateness through reductions of one selected case establishes a result confined to that case and test conditions. It does not establish that the same combination explains every late start, so the stated limit on generalization is licensed.",
  "uncertainty": "Whether the selected case actually shares an explanation with other late starts remains undetermined; the claim asserts only that generalization is not guaranteed.",
  "anomalies": []
}
